/*static*/const void* CTestImage::GetJpgCompressedImage_Bgr24(size_t* size, int* width, int* height)
{

    if (size != nullptr)
    {
        *size = sizeof(jpg_bgr24_data);
    }

    if (width != nullptr)
    {
        *width = 1024;
    }

    if (height != nullptr)
    {
        *height = 1024;
    }

    return jpg_bgr24_data;
}

